import { createHash, createHmac } from "node:crypto";

/**
 * breinhap#29: a minimal S3 client (AWS Signature Version 4, path-style) for the private MinIO bucket
 * that holds uploads. Only what uploads need: put, get, delete and a bucket check. No SDK: the requests
 * are few and fixed, and every one is signed here, so a key never leaves the process.
 *
 * The bucket is reachable only on management's internal network; nothing here ever builds a public or
 * presigned URL. Object keys are generated by the server (never a file name).
 */

const sha256 = (data) => createHash("sha256").update(data).digest("hex");
const hmac = (key, data) => createHmac("sha256", key).update(data).digest();
/** RFC 3986 encoding, as SigV4 wants it (slashes kept in paths). */
const encode = (value, keepSlash = false) =>
	encodeURIComponent(value)
		.replace(/[!'()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`)
		.replace(keepSlash ? /%2F/g : /$^/, "/");

/**
 * The Authorization header for a request. Exported for the AWS test vector.
 * `headers` are lower-case names; host and x-amz-* must be among them.
 */
export function signature({ method, path, query = "", headers, payloadHash, accessKeyId, secretAccessKey, region, date }) {
	const amzDate = date.toISOString().replace(/[:-]|\.\d{3}/g, "");
	const day = amzDate.slice(0, 8);
	const names = Object.keys(headers).map((h) => h.toLowerCase()).sort();
	const canonicalHeaders = names.map((h) => `${h}:${String(headers[h]).trim().replace(/\s+/g, " ")}\n`).join("");
	const signedHeaders = names.join(";");
	const canonical = [method, path, query, canonicalHeaders, signedHeaders, payloadHash].join("\n");
	const scope = `${day}/${region}/s3/aws4_request`;
	const toSign = ["AWS4-HMAC-SHA256", amzDate, scope, sha256(canonical)].join("\n");
	const key = hmac(hmac(hmac(hmac(`AWS4${secretAccessKey}`, day), region), "s3"), "aws4_request");
	const sig = createHmac("sha256", key).update(toSign).digest("hex");
	return `AWS4-HMAC-SHA256 Credential=${accessKeyId}/${scope}, SignedHeaders=${signedHeaders}, Signature=${sig}`;
}

export class StorageError extends Error {
	constructor(status, operation) {
		super(`storage ${operation} failed (${status})`);
		this.status = status;
		this.operation = operation;
	}
}

const KEY = /^[a-z0-9][a-z0-9/-]{0,200}$/;

export class S3Client {
	constructor({ endpoint, bucket, accessKeyId, secretAccessKey, region = "us-east-1", fetchImpl = fetch, now = () => new Date(), timeoutMs = 20_000 }) {
		const url = new URL(endpoint);
		if (!["http:", "https:"].includes(url.protocol) || url.pathname !== "/" || url.search) throw new Error("Invalid storage endpoint");
		if (!/^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$/.test(bucket ?? "")) throw new Error("Invalid bucket");
		if (!accessKeyId || !secretAccessKey) throw new Error("Storage credentials missing");
		Object.assign(this, { endpoint: url, bucket, accessKeyId, secretAccessKey, region, fetchImpl, now, timeoutMs });
	}

	async request(method, key, { body, contentType } = {}) {
		if (key !== "" && !KEY.test(key)) throw new Error("Invalid object key");
		const path = `/${encode(this.bucket)}${key ? `/${encode(key, true)}` : ""}`;
		const payloadHash = body ? sha256(body) : sha256("");
		const date = this.now();
		const headers = {
			host: this.endpoint.host,
			"x-amz-content-sha256": payloadHash,
			"x-amz-date": date.toISOString().replace(/[:-]|\.\d{3}/g, ""),
			...(contentType ? { "content-type": contentType } : {}),
		};
		const authorization = signature({ method, path, headers, payloadHash, accessKeyId: this.accessKeyId, secretAccessKey: this.secretAccessKey, region: this.region, date });
		const { host: _host, ...sent } = headers;
		return this.fetchImpl(new URL(path, this.endpoint), {
			method,
			headers: { ...sent, authorization },
			body,
			redirect: "error",
			signal: AbortSignal.timeout(this.timeoutMs),
		});
	}

	async put(key, body, contentType) {
		const res = await this.request("PUT", key, { body, contentType });
		await res.arrayBuffer().catch(() => {});
		if (!res.ok) throw new StorageError(res.status, "put");
	}

	/** The object's bytes, or null when it is gone. */
	async get(key) {
		const res = await this.request("GET", key);
		if (res.status === 404) {
			await res.arrayBuffer().catch(() => {});
			return null;
		}
		if (!res.ok) throw new StorageError(res.status, "get");
		return Buffer.from(await res.arrayBuffer());
	}

	async delete(key) {
		const res = await this.request("DELETE", key);
		await res.arrayBuffer().catch(() => {});
		if (!res.ok && res.status !== 404) throw new StorageError(res.status, "delete");
	}

	/** True when the bucket exists and these credentials may use it. */
	async ready() {
		const res = await this.request("HEAD", "");
		await res.arrayBuffer().catch(() => {});
		return res.ok;
	}
}

/** A test and development stand-in with the same interface. */
export class MemoryStorage {
	constructor() {
		this.objects = new Map();
	}
	async put(key, body) {
		this.objects.set(key, Buffer.from(body));
	}
	async get(key) {
		return this.objects.get(key) ?? null;
	}
	async delete(key) {
		this.objects.delete(key);
	}
	async ready() {
		return true;
	}
}
